#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_insert_nonempty_list_append(void) {
    // Setup: create a non-empty list (root is not NULL)
    node *root = NULL;
    // Insert first node to make list non-empty
    insert(&root, 1, 0, 5, 1);
    TEST_ASSERT_NOT_NULL(root);
    // Verify list has one node
    TEST_ASSERT_NULL(root->next);

    // Test: insert second node (this triggers path 2)
    // Conditions for path 2: *root != NULL, ptr->next == NULL (loop exits immediately)
    insert(&root, 2, 1, 4, 2);

    // Assertions
    // Root should still point to first node
    TEST_ASSERT_EQUAL_INT(1, root->ID);
    TEST_ASSERT_NOT_NULL(root->next);
    // Second node should be appended
    node *second = root->next;
    TEST_ASSERT_NOT_NULL(second);
    TEST_ASSERT_EQUAL_INT(2, second->ID);
    TEST_ASSERT_EQUAL_INT(1, second->AT);
    TEST_ASSERT_EQUAL_INT(4, second->BT);
    TEST_ASSERT_EQUAL_INT(2, second->priority);
    TEST_ASSERT_EQUAL_INT(0, second->CT);
    TEST_ASSERT_EQUAL_INT(0, second->WT);
    TEST_ASSERT_EQUAL_INT(0, second->TAT);
    TEST_ASSERT_NULL(second->next);

    // Cleanup
    helper_cleanup_process_queue(&root);
    TEST_ASSERT_NULL(root);
}

